CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', preferences text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING(auth.uid()=id) WITH CHECK(auth.uid()=id);
CREATE FUNCTION public.create_health_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE TRIGGER health_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_health_profile();
CREATE TABLE public.health_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL DEFAULT 'New health conversation', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.health_threads TO authenticated; GRANT ALL ON public.health_threads TO service_role;
ALTER TABLE public.health_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_threads ON public.health_threads FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.health_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.health_threads(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('user','assistant')), content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.health_messages TO authenticated; GRANT ALL ON public.health_messages TO service_role;
ALTER TABLE public.health_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_messages ON public.health_messages FOR ALL TO authenticated USING(auth.uid()=user_id AND EXISTS(SELECT 1 FROM public.health_threads t WHERE t.id=thread_id AND t.user_id=auth.uid())) WITH CHECK(auth.uid()=user_id AND EXISTS(SELECT 1 FROM public.health_threads t WHERE t.id=thread_id AND t.user_id=auth.uid()));
CREATE INDEX health_messages_thread ON public.health_messages(thread_id,created_at);
CREATE TABLE public.saved_conditions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,condition_slug text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,condition_slug));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.saved_conditions TO authenticated; GRANT ALL ON public.saved_conditions TO service_role;
ALTER TABLE public.saved_conditions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_saved ON public.saved_conditions FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);